"""Version ranges, as written in manifests and in index dependencies (docs/ranges.md)."""

import re

from pinset.errors import RangeError
from pinset.version import BUILD_RE, PRERELEASE_RE, Version

OPERATORS = ("<=", ">=", "<", ">", "=", "^", "~")
WILDCARDS = ("x", "X", "*")
NUMBER_RE = re.compile(r"0|[1-9][0-9]*")
SPACES = " \t"
SPACES_RE = re.compile(r"[ \t]+")
START = "0123456789xX*"

NEVER = ("never", None)


def _low(major, minor, patch):
    """A bound lower than every version of the release (docs/ranges.md, section 4)."""
    return Version(major, minor, patch, ("0",))


class Range:
    def __init__(self, text, alternatives, exact):
        self.text = text
        # Each alternative: (comparators, releases that may carry prereleases).
        self._alternatives = alternatives
        self._exact = exact

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        for comparators, allowed in self._alternatives:
            if version.is_prerelease() and version.release not in allowed:
                continue
            if all(_holds(op, bound, version) for op, bound in comparators):
                return True
        return False

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/resolve.md, section 4)."""
        return self._exact

    def __str__(self):
        return self.text


def _holds(op, bound, v):
    if op == ">=":
        return v >= bound
    if op == ">":
        return v > bound
    if op == "<":
        return v < bound
    if op == "<=":
        return v <= bound
    if op == "=":
        return v == bound
    return False


class _Partial:
    __slots__ = ("parts", "pre", "n")

    def __init__(self, parts, pre):
        self.parts = parts  # numbers given, 0 to 3
        self.n = len(parts)
        self.pre = pre

    @property
    def full(self):
        return self.n == 3

    def version(self):
        """The lower end, missing parts filled with zeros."""
        p = list(self.parts) + [0] * (3 - self.n)
        return Version(p[0], p[1], p[2], self.pre)

    def next_block(self):
        """The first version above the whole block (as `<X-0` bound)."""
        if self.n == 1:
            return _low(self.parts[0] + 1, 0, 0)
        return _low(self.parts[0], self.parts[1] + 1, 0)


def _parse_partial(text) -> _Partial:
    def bad():
        return RangeError("bad-version", f"not a partial version: {text!r}")

    rest = text
    build = pre = None
    if "+" in rest:
        rest, build = rest.split("+", 1)
    if "-" in rest:
        rest, pre = rest.split("-", 1)
    pieces = rest.split(".")
    if len(pieces) > 3:
        raise bad()
    parts = []
    wild = False
    for piece in pieces:
        if piece in WILDCARDS:
            wild = True
        elif NUMBER_RE.fullmatch(piece) and not wild:
            parts.append(int(piece))
        else:
            raise bad()
    if pre is not None or build is not None:
        if len(parts) != 3 or len(pieces) != 3:
            raise bad()
        if pre is not None and not PRERELEASE_RE.fullmatch(pre):
            raise bad()
        if build is not None and not BUILD_RE.fullmatch(build):
            raise bad()
    return _Partial(parts, tuple(pre.split(".")) if pre is not None else ())


def _comparators(op, p: _Partial):
    """The comparators for an operator and a partial version."""
    if p.n == 0:
        return [NEVER] if op in ("<", ">") else []
    lo = p.version()
    if p.full:
        if op in ("", "="):
            return [("=", lo)]
        if op in (">=", ">", "<", "<="):
            return [(op, lo)]
    elif op in ("", "="):
        return [(">=", lo), ("<", p.next_block())]
    elif op == ">=":
        return [(">=", lo)]
    elif op == ">":
        return [(">=", p.next_block().__class__(*p.next_block().release))]
    elif op == "<":
        return [("<", _low(*lo.release))]
    elif op == "<=":
        return [("<", p.next_block())]
    if op == "~":
        return [(">=", lo), ("<", _low(lo.major, lo.minor + 1, 0) if p.n >= 2 else _low(lo.major + 1, 0, 0))]
    # caret
    if p.n == 1 or lo.major > 0:
        upper = _low(lo.major + 1, 0, 0)
    elif p.n == 2 or lo.minor > 0:
        upper = _low(0, lo.minor + 1, 0)
    else:
        upper = _low(0, 0, lo.patch + 1)
